// generated by sitereal — where each entry is on this site, for the sitereal plugin.
import { emdashPosts } from "../data/sources/emdash-posts.js";

const SOURCES = [[emdashPosts, ""]];

/** A permalink as a path on its WordPress, the install's own folder taken off. */
const pathOf = (link, base) => {
  let p = '';
  try { p = new URL(link).pathname; } catch { return ''; }
  if (base && (p === base || p.startsWith(base + '/'))) p = p.slice(base.length);
  return '/' + p.replace(/^\/+|\/+$/g, '');
};

export async function GET() {
  const entries = {};
  for (const [ask, base] of SOURCES) {
    for (const row of await ask()) {
      if (typeof row?.link !== 'string' || typeof row?.url !== 'string' || !row.url.startsWith('/')) continue;
      const from = pathOf(row.link, base);
      if (from) entries[from] ??= row.url;
    }
  }
  return new Response(JSON.stringify({ generator: 'sitereal', entries }, null, 1), {
    headers: { 'Content-Type': 'application/json; charset=utf-8' },
  });
}
